KG42.register("rules-1f42e13ce9d505258637ee83",{"id":"45-heat_pump_flexibility::v141-c-R002","paper":"45-heat_pump_flexibility","record":{"rule_id":"v141-c-R002","mechanism_id":"v141-a-M01","name":"Supply submission","process_stage":"bidding","market_meaning":"Supply offers are submitted based on optimal schedules; their quantities are based on electrical-demand or generation forecasting and calculated using model predictive control. Scope: Supply submissions by prosumer agents in the modeled local energy market.","independence_rationale":"Relations governed by the approved function bidding.supply under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.supply"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Supply submissions by prosumer agents in the modeled local energy market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e14"]},"x":[{"variable_id":"v141-c-R002-X001","symbol":"p_{t,offer}","meaning":"Offer price submitted by a selling prosumer at current time step t for delivery period t_d.","kind":"operational","domain":"t_d − ΔT ≤ t ≤ t_d; price trajectory defined by Eq. (3) for a selling prosumer","unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-e14","v141-b-g01-e15"]}],"theta":[{"parameter_id":"v141-c-R002-P001","symbol":"p_{max}","meaning":"Price ceiling used in the supply offer-price increment definition.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e15"]},{"parameter_id":"v141-c-R002-P002","symbol":"p_{min}","meaning":"Price floor used in the supply offer-price trajectory and increment definition.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e15"]},{"parameter_id":"v141-c-R002-P003","symbol":"ΔT","meaning":"Trading horizon selected by the prosumer.","value":{"kind":"text","number_value":null,"text_value":"selected by the prosumer; can range from 6 to 24 h"},"unit":"h","indices":[],"evidence_ids":["v141-b-g01-e15"]},{"parameter_id":"v141-c-R002-P004","symbol":"Δp","meaning":"Price increment in the next time step when the bids are not accepted completely; defined by Eq. (4).","value":{"kind":"symbolic","number_value":null,"text_value":"(p_{max} - p_{min}) / ΔT"},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e15"]},{"parameter_id":"v141-c-R002-P005","symbol":"t","meaning":"Current time step.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e15"]},{"parameter_id":"v141-c-R002-P006","symbol":"t_d","meaning":"Delivery period.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e15"]}],"phi":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"Supply offers are submitted based on optimal schedules; their quantities are based on electrical-demand or generation forecasting and calculated using model predictive control. Scope: Supply submissions by prosumer agents in the modeled local energy market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e14"]},{"constraint_id":"v141-c-R002-C002","kind":"mathematical","role":"core","statement":"For a selling prosumer, the offer price at current time step t for delivery period t_d follows p_{t,offer} = p_min + (t_d − t) Δp over t_d − ΔT ≤ t ≤ t_d.","expression":"p_{t,offer} = p_{min} + (t_d - t)\\Delta p, \\quad \\forall t_d - \\Delta T \\leq t \\leq t_d","formalization_origin":"source","template_id":null,"members":["bidding.supply"],"variable_refs":["v141-c-R002-X001"],"parameter_refs":["v141-c-R002-P002","v141-c-R002-P003","v141-c-R002-P004","v141-c-R002-P005","v141-c-R002-P006"],"evidence_ids":["v141-b-g01-e14","v141-b-g01-e15"]},{"constraint_id":"v141-c-R002-C003","kind":"mathematical","role":"supporting","statement":"The price increment used in the offer-price trajectory is Δp = (p_max − p_min) / ΔT.","expression":"\\Delta p = \\frac{p_{max} - p_{min}}{\\Delta T}","formalization_origin":"source","template_id":null,"members":["bidding.supply"],"variable_refs":[],"parameter_refs":["v141-c-R002-P001","v141-c-R002-P002","v141-c-R002-P003","v141-c-R002-P004"],"evidence_ids":["v141-b-g01-e15"]}],"pi":[{"evidence_id":"v141-b-g01-e05","location":{"location_id":"src-115be449fd-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":null,"section":null,"anchor_text":"3. submitting bids: send their bids and offers to the LEM based on to the optimal schedules prior to","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"In general, prosumers must complete the following steps to achieve energy exchange in the LEM:\n1. forecasts: make forecasts about weather, demands, and electricity prices;\n2. model-predictive control: use the model-predictive control (MPC) to generate the optimal schedules for their flexible loads such HPs, EVs, and batteries;\n3. submitting bids: send their bids and offers to the LEM based on the optimal schedules prior to the delivery time\n4. market clearing: match the demand and supply and clear the market;\n5. receiving results: receives the market clearing results for the delivery time after the market clearing;\n6. real-time control: use real-time controller to adjust the operating states of the flexible loads at the delivery time according to the electricity procured from the LEM;\n7. settlement: settle the consumption or generation soon after the electricity has been delivered\n\nThe steps 1 to 5 should be repeated for every rolling horizon prior to the delivery time step. Prosumers should check the clearing results from the previous rolling horizon to ensure that the procured electricity is sufficient for their energy demand at the time step of delivery."},{"evidence_id":"v141-b-g01-e14","location":{"location_id":"src-115be449fd-p04-c2r3__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"ed The double-sided auction process is visualized in Fig. 3. The uniform le pricing for the double-s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Prosumers must decide on the quantity and pricing of their bids prior to the delivery interval. The bid quantity is based on electrical demand or generation forecasting, calculated using model predictive control discussed in Section 2.3. A linear trading strategy is used for the bid prices. Prosumers who buy energy aim to purchase it at the lowest price initially. After each round of market clearing, any remaining unaccepted bids' prices gradually increase until prosumers offer the highest price they are willing to pay in the final time step before the delivery period. Conversely, prosumers who sell energy begin by bidding at the highest price and gradually decrease the price as the delivery time approaches. This behavior is described by the following equation:"},{"evidence_id":"v141-b-g01-e15","location":{"location_id":"src-115be449fd-p04-c2r3__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"ed The double-sided auction process is visualized in Fig. 3. The uniform le pricing for the double-s","equation_id":"2-4","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"p_{t,bid} = p_{max} − (t_d − t)Δp, ∀ t_d − ΔT ⩽ t ⩽ t_d (2)\np_{t,offer} = p_{min} + (t_d − t)Δp, ∀ t_d − ΔT ⩽ t ⩽ t_d (3)\nΔp = (p_{max} − p_{min}) / ΔT (4)\nwhere t and t_d represent the current time step and the delivery period. p_{max} and p_{min} are the price ceiling and floor. ΔT is the trading horizon selected by the prosumer, which can range from 6 to 24 h. Δp is the price increment in the next time step when the bids are not accepted completely."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-activation","v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-matching","v141-a-M01-participation","v141-a-M01-settlement"],"extras":{"decision_anchor":"bidding.supply","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e05","quote":"3. submitting bids: send their bids and offers to the LEM based on the optimal schedules prior to the delivery time"},{"evidence_id":"v141-b-g01-e14","quote":"The bid quantity is based on electrical demand or generation forecasting, calculated using model predictive control discussed in Section 2.3."}]],"C2_formalization":{"graph_sha256":"197a18474380cabfbceb84e3a18779b47845dcc67a5d3be7854d4c281c66ea39","applicability":"formalized","reason":"Formalizes the supported selling-offer price component of supply submission. The supplied B evidence, which remains unreviewed candidate support, gives Eq. (3) and Eq. (4): p_{t,offer}=p_min+(t_d−t)Δp for t_d−ΔT≤t≤t_d and Δp=(p_max−p_min)/ΔT. The quantity side ('quantity is based on electrical demand or generation forecasting, calculated using model predictive control') has no explicit quantity formula in the supplied evidence, so the original C001 procedural constraint remains not formalized. No additional graph edge is needed for the unary price equation; the frozen graph contains only bidding.supply.","bindings":[{"object_id":"v141-c-R002-X001","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The selling prosumer offer price is the operational bidding output attached to the frozen supply-submission node. The frozen rule has no edges, and the price trajectory itself is unary with respect to bidding.supply."},{"object_id":"v141-c-R002-P001","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The price ceiling is a source-defined input to the supply offer-price increment used in bidding.supply."},{"object_id":"v141-c-R002-P002","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The price floor is a source-defined input to both the selling offer-price trajectory and its increment in bidding.supply."},{"object_id":"v141-c-R002-P003","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The selected trading horizon parameterizes the supply offer-price trajectory and increment."},{"object_id":"v141-c-R002-P004","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The price increment parameterizes the supply offer-price trajectory when offers are not accepted completely."},{"object_id":"v141-c-R002-P005","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The current time step indexes the source supply offer-price equation."},{"object_id":"v141-c-R002-P006","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The delivery period indexes the source supply offer-price equation."},{"object_id":"v141-c-R002-C002","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"Formalizes the source Eq. (3) supply offer-price trajectory as a unary constraint on the frozen bidding.supply node; no edge is available or required for this equation."},{"object_id":"v141-c-R002-C003","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"Formalizes the source Eq. (4) increment definition supporting the supply offer-price equation on bidding.supply."}],"revision_requests":[]}},"quarantined_references":[]}});
